import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const secretsDir = fileURLToPath(new URL("../../../.secrets/", import.meta.url));

function valueIn(file: string, name: string): string | undefined {
  const line = readFileSync(`${secretsDir}${file}`, "utf8").split("\n").find((l) => l.startsWith(`${name}=`));
  return line?.slice(name.length + 1);
}

/** Reads one value of a cell's secrets file (`.secrets/cells/<cell>.env`, generated by `make secrets`). */
export function cellSecret(cell: string, name: string): string {
  const value = valueIn(`cells/${cell}.env`, name);
  if (value === undefined) throw new Error(`${name} missing from .secrets/cells/${cell}.env (run make secrets)`);
  return value;
}

/**
 * Reads one value generated by `make secrets`: the platform's own file first, then the default
 * stack's cell (pool-1), which is the cell every test talks to unless it names another.
 */
export function secret(name: string): string {
  return valueIn("dev.env", name) ?? cellSecret("pool-1", name);
}

/** Where `make secrets` writes the per-cell secrets the control plane holds, mounted into it in Compose. */
export const platformCredentialsDir = `${secretsDir}mounts/platform`;

/** Where `make secrets` writes each cell's tenant-context secret for the edge, mounted into it in Compose. */
export const edgeCredentialsDir = `${secretsDir}mounts/edge`;
